<script lang="ts">
import {onMount,tick} from "svelte";import {invoke} from "@tauri-apps/api/core";import {t} from "$lib/i18n/index.svelte";import type {Connection,ConnectionSummary} from "$lib/types";
let {connectionId,focusToken,width,onedit}:{connectionId:string|null;focusToken:number;width:number;onedit:(c:ConnectionSummary)=>void}=$props();
let connection=$state<Connection|null>(null),summaries=$state<ConnectionSummary[]>([]),query=$state(""),loading=$state(false),error=$state(""),searchInput=$state<HTMLInputElement|null>(null),version=0;
async function load(){const current=++version;if(!connectionId){connection=null;error="";return;}loading=true;error="";try{const [full,all]=await Promise.all([invoke<Connection|null>("conn_get",{id:connectionId}),invoke<ConnectionSummary[]>("conn_list")]);if(current!==version)return;connection=full;summaries=all;if(!full)error=t("properties.missing");}catch(e){if(current===version)error=String(e);}finally{if(current===version)loading=false;}}
onMount(()=>{void load();});$effect(()=>{connectionId;void load();});$effect(()=>{if(focusToken!==lastFocusToken){lastFocusToken=focusToken;void tick().then(()=>{searchInput?.focus();searchInput?.select();});}});
const authLabel=$derived(connection?.auth.type==="password"?t("properties.auth.password"):connection?.auth.type==="key"?t("properties.auth.key"):connection?t("properties.auth.agent"):"");
const rows=$derived.by(()=>{if(!connection)return[];const jumps=connection.jump.filter(id=>!connection!.jump_disabled.includes(id)).map(id=>summaries.find(x=>x.id===id)?.name??id).join(" → ");const forwards=connection.tunnels.filter(x=>x.enabled).map(x=>x.kind==="dynamic"?"SOCKS "+x.bind:(x.kind==="local"?"Local ":"Remote ")+x.bind+" → "+x.dest).join(", ");const values:[string,string][]=[[t("properties.name"),connection.name],[t("properties.host"),connection.host],[t("properties.port"),String(connection.port)],[t("properties.username"),connection.user],[t("properties.authMethod"),authLabel],...(connection.auth.type==="key"?[[t("properties.sshKey"),connection.auth.path] as [string,string]]:[]),[t("properties.jumpHosts"),jumps||t("properties.none")],[t("properties.keepalive"),connection.keepalive_secs+" s"],[t("properties.protected"),connection.protected?t("common.yes"):t("common.no")],[t("properties.tunnels"),forwards||t("properties.none")],[t("properties.highlight"),connection.highlight.join(", ")||t("properties.none")]];const q=query.trim().toLocaleLowerCase();return values.filter(([a,b])=>!q||a.toLocaleLowerCase().includes(q)||b.toLocaleLowerCase().includes(q));});
function edit(){if(!connection)return;onedit({id:connection.id,name:connection.name,host:connection.host,port:connection.port,user:connection.user,jump:connection.jump,jump_disabled:connection.jump_disabled,tunnel_count:connection.tunnels.filter(x=>x.enabled).length,protected:connection.protected});}
</script>
<aside class="properties-pane" aria-label={t("properties.title")} style:width={`${width}px`} onpointerdown={() => searchInput?.focus()}><div class="properties-head"><strong>{t("properties.title")}</strong>{#if connection}<button class="edit-button" title={t("properties.edit")} aria-label={t("properties.edit")} onclick={edit}><svg viewBox="0 0 24 24"><path d="M4 20h4l11-11a2.1 2.1 0 0 0-4-4L4 16v4Z"/><path d="m13.5 6.5 4 4"/></svg></button>{/if}</div><div class="properties-search-wrap"><input bind:this={searchInput} bind:value={query} type="search" placeholder={t("properties.search")} aria-label={t("properties.searchLabel")}/></div>
{#if loading}<p class="state">{t("properties.loading")}</p>{:else if error}<p class="state error" role="alert">{error}</p>{:else if !connection}<p class="state">{t("properties.selectConnection")}</p>{:else if !rows.length}<p class="state">{t("properties.noMatches",{query})}</p>{:else}<div class="property-grid">{#each rows as [label,value] (label)}<div class="property-label">{label}</div><div class="property-value" title={value}>{value}</div>{/each}</div>{/if}</aside>
<style>
.properties-pane{flex:0 0 auto;min-width:250px;max-width:450px;min-height:0;display:flex;flex-direction:column;overflow:hidden;background:var(--surface);border-right:1px solid var(--border);box-sizing:border-box}.properties-head{min-height:2.25rem;flex:0 0 auto;display:flex;align-items:center;justify-content:space-between;padding:0 .65rem;border-bottom:1px solid var(--border);color:var(--muted);font-size:.72rem;text-transform:uppercase;letter-spacing:.04em}.edit-button{width:28px;height:28px;flex:0 0 28px;display:inline-flex;align-items:center;justify-content:center;padding:0;color:var(--muted);background:transparent;border:1px solid transparent;border-radius:4px;cursor:pointer}.edit-button:hover{color:var(--accent);background:var(--surface-hover);border-color:var(--border)}.edit-button svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}.properties-search-wrap{flex:0 0 auto;padding:.5rem;background:var(--surface)}.properties-search-wrap input{width:100%;min-height:28px;box-sizing:border-box;padding:.3rem .5rem;color:var(--text);background:var(--surface-deep);border:1px solid var(--border);border-radius:4px;font:inherit;font-size:.72rem}.properties-search-wrap input:focus{outline:2px solid var(--accent);outline-offset:1px}.property-grid{min-height:0;overflow:auto;display:grid;grid-template-columns:100px minmax(0,1fr);align-content:start;gap:3px 4px;padding:.5rem;font:.72rem/1.35 "Cascadia Mono",Consolas,monospace}.property-label{min-width:0;padding:.38rem .4rem;display:flex;align-items:center;color:var(--muted);background:color-mix(in srgb,var(--surface-raised) 45%,transparent);border-radius:3px 0 0 3px;overflow-wrap:anywhere}.property-value{min-width:0;padding:.38rem .45rem;color:var(--text);background:var(--surface-deep);border:1px solid var(--border);border-radius:0 3px 3px 0;overflow-wrap:anywhere;user-select:text}.state{margin:0;padding:.75rem;color:var(--muted);font-size:.72rem}.state.error{color:var(--danger)}
</style>